GAS_FUELS = {"焦炉煤气", "高炉煤气", "其它煤气", "天然气", "转炉煤气", "其它气体燃料"}
WASTE_FUELS = {"城市生活垃圾（用于燃料）", "工业废料（用于燃料）"}
UNMAPPABLE_FUELS = {"生物燃料", "其他燃料"}  # 表D.1无对应行

# 燃烧技术映射: 基102名称 -> 表D.1技术行
TECH_MAP = {"煤粉炉": "煤粉炉", "循环流化床锅炉": "流化床炉", "层燃炉": "自动炉排层燃炉",
            "链条炉": "自动炉排层燃炉", "抛煤机炉": "自动炉排层燃炉", "其他层燃炉": "自动炉排层燃炉"}
# 气体燃料在表D.1中统一为"燃气锅炉"技术行; 燃气轮机亦采用该行(近似, 见异常清单)
GAS_TECH = "燃气锅炉"
LIQUID_TECH = "燃油锅炉"

POLLUTANTS = ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC", "NH3"]

D44 = {4411, 4412, 4417, 4419, 4430}
INDUSTRY_INDUSTRIAL_PREFIX = {6, 7, 8, 9, 10, 11, 12}  # B06~12 采矿业
D45 = {4511, 4512, 4520}


def industry_to_class(code):
    """按行业类别代码判定源类。返回 (decided_target, reason_code)"""
    c = int(code)
    if c in D44:
        return "POWER", "CLASS_POWER_D44"
    # 制造业 C13~43: 13xx~43xx; 采矿业 B06~12: 6xx~12xx(3-4位)
    if c in D45:
        return "INDUSTRIAL", "CLASS_INDUSTRIAL_D45"
    if 1300 <= c <= 4399:
        return "INDUSTRIAL", "CLASS_INDUSTRIAL_C"
    if c >= 600 and c <= 1299:
        return "INDUSTRIAL", "CLASS_INDUSTRIAL_B"
    return "OUT_OF_SCOPE", "CLASS_OUT_OF_SCOPE"


def fuel1_of(row):
    return row["燃料1类型"] if pd.notna(row["燃料1类型"]) else None


def tech_of(row):
    if pd.notna(row["电站锅炉/燃气轮机编号"]):
        return row["电站锅炉燃烧技术"] if pd.notna(row["电站锅炉燃烧技术"]) else None
    return row["工业锅炉燃烧技术"] if pd.notna(row["工业锅炉燃烧技术"]) else None


def lnb_of(row):
    """是否采用低氮燃烧技术 (电站/工业列按设备类型取)"""
    if pd.notna(row["电站锅炉/燃气轮机编号"]):
        v = row["是否采用低氮燃烧技术"]
    else:
        v = row["是否采用低氮燃烧技术.1"]
    return 1 if (pd.notna(v) and str(v).strip() == "是") else 0


def num(v):
    try:
        f = float(v)
        return f if math.isfinite(f) else None
    except (TypeError, ValueError):
        return None


# ---------------------------------------------------------------- 治理设施 ----------------------------------------------------------------
def load_facilities():
    fac = pd.read_excel(os.path.join(IN, "基101-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    return fac


def build_facility_map(fac):
    """key: (统一社会信用代码, 排放口代码) -> list of facility dicts"""
    m = {}
    for r in fac.itertuples(index=False):
        credit = r[2] if pd.notna(r[2]) else None
        org = r[1] if pd.notna(r[1]) else None
        key_credit = credit if credit else org
        if key_credit is None:
            continue
        outlet = r[11] if pd.notna(r[11]) else None
        if outlet not in ("DZGL", "GYGL"):
            continue
        k = (str(key_credit), outlet)
        m.setdefault(k, []).append({
            "name": r[10] if pd.notna(r[10]) else None,
            "process": r[15] if pd.notna(r[15]) else None,
            "eff": num(r[16]),
        })
    return m


def match_a1(kw_list, process, default):
    if process is None:
        return None
    p = str(process)
    for kw, v in kw_list:
        if kw in p:
            return v
    return default


def control_eta(facilities, name_kw, a1_kw, default_a1):
    """计算某类治理设施的去除效率。返回 (eta, method_desc, eff_used) 或 (None, ...) 表示未知"""
    cands = [f for f in facilities if f["name"] and name_kw in f["name"]]
    if not cands:
        return None, "NO_FACILITY", None
    best = None
    for f in cands:
        if f["eff"] is not None and 0 <= f["eff"] <= 100:
            v = f["eff"] / 100.0
            if best is None or v > best[0]:
                best = (v, "REPORTED", f)
        elif f["eff"] is None:
            a1 = match_a1(a1_kw, f["process"], default_a1)
            if a1 is not None:
                v = a1 / 100.0
                if best is None or v > best[0]:
                    best = (v, "TABLE_A1", f)
    if best is None:
        return None, "UNKNOWN", None
    return best[0], best[1], best[2]


def pm_eta(facilities):
    """除尘设施: 返回 (eta_pm25, eta_pm25_10, method)"""
    cands = [f for f in facilities if f["name"] and "除尘" in f["name"]]
    if not cands:
        return 0.0, 0.0, "NO_FACILITY"
    best25 = best10 = None
    for f in cands:
        if f["eff"] is not None and 0 <= f["eff"] <= 100:
            v = f["eff"] / 100.0
            if best25 is None or v > best25[0]:
                best25 = (v, "REPORTED")
            if best10 is None or v > best10[0]:
                best10 = (v, "REPORTED")
        else:
            a25 = match_a1(A1_PM25, f["process"], A1_OTHER_DUST[0])
            a10 = match_a1(A1_PM25_10, f["process"], A1_OTHER_DUST[1])
            if a25 is not None and (best25 is None or a25 / 100.0 > best25[0]):
                best25 = (a25 / 100.0, "TABLE_A1")
            if a10 is not None and (best10 is None or a10 / 100.0 > best10[0]):
                best10 = (a10 / 100.0, "TABLE_A1")
    if best25 is None or best10 is None:
        return None, None, "UNKNOWN"
    return best25[0], best10[0], best25[1]


# ---------------------------------------------------------------- 计算 ----------------------------------------------------------------
def component_ef(sector, fuel_name, tech, coal_qual, capacity_mw):
    """计算一个燃料组分的各污染物产生系数。
    返回 (dict pollutant->(ef, mode, unit, detail)), 或 (None, reason) 表示无法计算。
    """
    if fuel_name in WASTE_FUELS:
        return None, "WASTE_FUEL"
    if fuel_name in UNMAPPABLE_FUELS:
        return None, "FUEL_NO_EF"
    d1_fuel = FUEL_MAP.get(fuel_name)
    if d1_fuel is None:
        return None, "FUEL_NO_EF"
    if d1_fuel == "煤炭":
        t = TECH_MAP.get(tech) if tech else None
        if t is None:
            return None, "TECH_UNKNOWN"
        row = D1[sector]["煤炭"][t]
        cp = C_PARAMS[sector][t]
    elif d1_fuel in ("焦炭", "煤矸石"):
        # 不分技术行
        row = D1[sector][d1_fuel]["不分技术"]
        t = TECH_MAP.get(tech) if tech else None
        # 物料衡算所需 ar/f: 表C.1~C.3 仅列"煤炭"; 煤矸石/焦炭采用本设备燃煤技术对应参数(近似)
        cp = C_PARAMS[sector][t] if t else C_PARAMS[sector]["煤粉炉"]
    elif d1_fuel in GAS_FUELS:
        row = D1[sector][d1_fuel][GAS_TECH]
        cp = None
    else:
        row = D1[sector][d1_fuel][LIQUID_TECH]
        cp = None

    ef = {}
    for p in POLLUTANTS:
        if p == "NH3":
            ef[p] = (0.0, "ZERO_STANDARD", "g/kg", "表D.1无NH3产生系数,取0")
            continue
        v = row.get(p)
        if p == "SO2" and v == "MB":
            s = coal_qual.get("s")
            if s is None:
                return None, "SO2_NO_SULFUR"
            ef_s = 2.0 * s * (1.0 - SR[sector])
            ef[p] = (ef_s, "MASS_BALANCE", "g/kg", f"EF_SO2=2×S×({1.0-SR[sector]:.2f}), S={s}")
            continue
        if p in ("PM25", "PM10", "BC", "OC") and v == "MB":
            if coal_qual.get("ash") is None:
                return None, "PM_NO_ASH"
            ar = cp["ar"]
            ef_pm10_base = 10.0 * coal_qual["ash"] * (1.0 - ar)
            if p == "PM25":
                ef[p] = (ef_pm10_base * cp["f25"], "MASS_BALANCE", "g/kg",
                         f"EF_PM2.5=10×Aar×({1-ar:.2f})×{cp['f25']}")
            elif p == "PM10":
                ef[p] = (ef_pm10_base * cp["f10"], "MASS_BALANCE", "g/kg",
                         f"EF_PM10=10×Aar×({1-ar:.2f})×{cp['f10']}")
            elif p == "BC":
                ef[p] = (ef_pm10_base * cp["f25"] * cp["fBC"], "MASS_BALANCE", "g/kg",
                         f"EF_BC=EF_PM2.5×{cp['fBC']}")
            else:
                ef[p] = (ef_pm10_base * cp["f25"] * cp["fOC"], "MASS_BALANCE", "g/kg",
                         f"EF_OC=EF_PM2.5×{cp['fOC']}")
            continue
        if p == "NOx" and v == "CAPACITY":
            if capacity_mw is None:
                return None, "NOX_NO_CAPACITY"
            if capacity_mw <= 100:
                v = 8.96
            elif capacity_mw < 300:
                v = 8.19
            else:
                v = 7.21
            ef[p] = (v, "TABLE_D1_CAPACITY", "g/kg", f"表D.1注b: 装机容量{capacity_mw}MW")
            continue
        ef[p] = (float(v), "TABLE_D1", row["unit"], "表D.1")
    return ef, None


def activity_value(row, n):
    """n=1或2, 返回 (value, unit, quality_dict)"""
    if n == 1:
        v = num(row["燃料1消耗量"])
        u = row["燃料1消耗量单位"] if pd.notna(row["燃料1消耗量单位"]) else None
        qual = {"s": num(row["燃料一平均收到基含硫量"]), "ash": num(row["燃料一平均收到基灰分（%）"])}
        fuel = fuel1_of(row)
    else:
        v = num(row["燃料2消耗量"])
        u = row["燃料2消耗量单位"] if pd.notna(row["燃料2消耗量单位"]) else None
        qual = {"s": num(row["燃料二平均收到基含硫量"]), "ash": num(row["燃料二平均收到基灰分（%）"])}
        fuel = row["燃料2类型"] if pd.notna(row["燃料2类型"]) else None
    return v, u, qual, fuel


def to_tons(activity, unit):
    """活动水平 -> 质量当量(kg)。气体按万m3。返回kg数(用于与g/kg或g/m3系数相乘)及显示单位"""
    if unit and "万立方米" in str(unit):
        return activity * 1e4, "万立方米"  # m3
    return activity * 1000.0, "吨"  # kg


def calc_source(row, facilities):
    """返回 dict: components, per-pollutant results"""
    sector = "热力生产和供应" if int(row["行业类别代码"]) == 4430 else "电力生产"
    cap_mw = num(row["对应机组装机容量（万千瓦）"])
    cap_mw = cap_mw * 10.0 if cap_mw is not None else None
    tech = tech_of(row)

    comps = []
    for n in (1, 2):
        v, u, qual, fuel = activity_value(row, n)
        if fuel is None or v is None:
            continue
        if v <= 0:
            continue
        comps.append({"id": f"F{n}", "fuel": fuel, "value": v, "unit": u, "qual": qual})

    # 每个污染物: 汇总各组分
    results = {}
    for p in POLLUTANTS:
        gen_comp, emi_comp = [], []
        insufficient_reason = None
        for c in comps:
            ef, reason = component_ef(sector, c["fuel"], tech, c["qual"], cap_mw)
            if reason is not None:
                insufficient_reason = f"{c['id']}:{reason}"
                break
            efv = ef[p][0]
            kg_act, disp_unit = to_tons(c["value"], c["unit"])
            if disp_unit == "万立方米":
                # EF g/m3: E(t) = m3 × g/m3 / 1e6
                gen = kg_act * efv / 1e6
            else:
                # EF g/kg: E(t) = kg × g/kg / 1e6
                gen = kg_act * efv / 1e6
            gen_comp.append({"id": c["id"], "gen": gen, "ef": efv, "ef_mode": ef[p][1], "ef_unit": ef[p][2], "ef_detail": ef[p][3]})
        if insufficient_reason is not None:
            results[p] = {"status": "information_insufficient", "reason": insufficient_reason,
                          "gen": None, "emi": None, "comp": comps}
            continue
        results[p] = {"status": "calculated", "gen": sum(x["gen"] for x in gen_comp),
                      "emi": None, "comp": gen_comp}
    return sector, comps, results


def apply_control(sector, row, facilities, results):
    """按污染物应用治理效率 η"""
    eta = {}
    # SO2: 脱硫（酸）设施
    eta_so2, so2_mode, _ = control_eta(facilities, "脱硫", A1_SO2, 40)
    eta["SO2"] = (0.0 if eta_so2 is None else eta_so2, "NO_FACILITY" if so2_mode == "NO_FACILITY" else so2_mode)
    # NOx: 脱硝设施 + 低氮燃烧
    lnb = lnb_of(row)
    eta_nox, nox_mode, nox_fac = control_eta(facilities, "脱硝", A1_NOX, 20)
    if nox_mode == "NO_FACILITY":
        eta_nox_eff = 0.0
        nox_desc = "NO_FACILITY"
    else:
        eta_nox_eff = eta_nox
        nox_desc = nox_mode
    proc_has_lnb = False
    if nox_fac is not None and nox_fac["process"]:
        proc_has_lnb = "低氮燃烧" in str(nox_fac["process"])
    if lnb and not proc_has_lnb:
        if nox_desc == "NO_FACILITY":
            eta_nox_eff = 0.22
            nox_desc = "LNB_22"
        else:
            eta_nox_eff = 1.0 - (1.0 - 0.22) * (1.0 - eta_nox_eff)
            nox_desc = nox_desc + "+LNB_SERIES"
    elif lnb and proc_has_lnb:
        pass  # 工艺名已含低氮燃烧(表A.1合并值), 不重复叠加
    eta["NOx"] = (eta_nox_eff, nox_desc)
    # CO: 无治理
    eta["CO"] = (0.0, "NO_FACILITY")
    # VOC: 电力热力源锅炉烟气VOCs无对应末端治理设施挂接(DZGL/GYGL无VOCs设施) -> 0
    eta["VOC"] = (0.0, "NO_FACILITY")
    # PM: 除尘设施
    e25, e10, pm_mode = pm_eta(facilities)
    eta["PM2.5"] = (e25, pm_mode)
    eta["PM10"] = (e10, pm_mode)
    eta["BC"] = (e25, pm_mode)
    eta["OC"] = (e25, pm_mode)
    # NH3: 无治理(EF=0)
    eta["NH3"] = (0.0, "NO_FACILITY")

    for p, r in results.items():
        if r["status"] != "calculated":
            continue
        e, mode = eta[p]
        if e is None:
            r["status"] = "information_insufficient"
            r["reason"] = "CONTROL_EFF_UNKNOWN"
            r["emi"] = None
            continue
        r["emi"] = r["gen"] * (1.0 - e)
        r["eta"] = e
        r["eta_mode"] = mode
    return eta


def main():
    df = pd.read_excel(os.path.join(IN, "基102-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    fac = pd.read_excel(os.path.join(IN, "基101-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    with open(os.path.join(IN, "source_identity_index.json"), encoding="utf-8") as f:
        idx = json.load(f)
    recs = idx["records"]
    assert len(recs) == len(df), (len(recs), len(df))
    # source_id by source_row (1-based Excel row; header=1)
    sid_by_row = {r["source_row"]: r["source_id"] for r in recs}
    df["source_id"] = df.index.map(lambda i: sid_by_row[i + 2])

    fac_map = build_facility_map(fac)

    decisions = []
    items = []
    dispositions = []
    exceptions = []
    stats = {"calculated": 0, "not_involved": 0, "information_insufficient": 0, "source_data_invalid": 0}

    for row in df.itertuples(index=False):
        sid = row[93]
        cls, cls_reason = industry_to_class(row[6])
        fuel1 = fuel1_of(row)
        is_power_device = pd.notna(row[10])
        outlet_code = "DZGL" if is_power_device else "GYGL"

        if cls == "POWER":
            if fuel1 in WASTE_FUELS:
                decided, disp, reason = "OUT_OF_SCOPE", "out_of_scope", "WASTE_INCINERATION_CH13"
            else:
                decided, disp, reason = "POWER", "in_scope", cls_reason
        else:
            decided, disp, reason = cls, "out_of_scope", cls_reason

        decisions.append({"source_id": sid, "requested_target": "POWER", "decided_target": decided,
                          "disposition": disp, "reason_code": reason})
        dispositions.append({"source_id": sid, "target": decided, "disposition": disp, "reason_code": reason})

        if decided != "POWER":
            for p in POLLUTANTS:
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "not_involved",
                              "method": "", "activity_record_json": "[]", "parameter_record_json": "[]",
                              "control_record_json": "[]", "generation_t": "", "emission_t": "",
                              "standard_reference": "", "reason_code": "NOT_IN_REQUESTED_TARGET"})
                stats["not_involved"] += 1
            continue

        # POWER 源: 计算
        credit = row[2] if pd.notna(row[2]) else (row[1] if pd.notna(row[1]) else None)
        facilities = fac_map.get((str(credit), outlet_code), []) if credit else []
        sector, comps, results = calc_source(row, facilities)
        if not comps:
            for p in POLLUTANTS:
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "information_insufficient",
                              "method": "", "activity_record_json": "[]", "parameter_record_json": "[]",
                              "control_record_json": "[]", "generation_t": "", "emission_t": "",
                              "standard_reference": "T/CSES 144-2024 7.2", "reason_code": "NO_ACTIVITY"})
                stats["information_insufficient"] += 1
            continue
        apply_control(sector, row, facilities, results)

        for p in POLLUTANTS:
            r = results[p]
            if r["status"] == "calculated":
                gen = round(r["gen"], 6)
                emi = round(r["emi"], 6)
                # 构建三个JSON数组 (组件对齐)
                act_arr = []
                par_arr = []
                ctl_arr = []
                for c in r["comp"]:
                    act_arr.append({"component_id": c["id"], "value": c["gen"], "unit": "吨"})
                    par_arr.append({"component_id": c["id"], "parameter_id": f"EF_{p}",
                                    "mode": c["ef_mode"], "value": c["ef"], "unit": c["ef_unit"]})
                    if p == "PM10":
                        ctl_arr.append({"component_id": c["id"], "method": r.get("eta_mode", "NO_FACILITY"),
                                        "efficiency": r.get("eta", 0.0),
                                        "fine_efficiency": r.get("eta", 0.0),
                                        "coarse_efficiency": r.get("eta", 0.0)})
                    else:
                        ctl_arr.append({"component_id": c["id"], "method": r.get("eta_mode", "NO_FACILITY"),
                                        "efficiency": r.get("eta", 0.0),
                                        "fine_efficiency": "", "coarse_efficiency": ""})
                # 修正: activity数组记录的是活动水平而非产生量
                act_arr = []
                for c in comps:
                    act_arr.append({"component_id": c["id"], "value": c["value"], "unit": c["unit"]})
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "calculated",
                              "method": "E=A×EF×(1−η) (公式2)" if r.get("eta_mode") else "E=A×EF (公式2)",
                              "activity_record_json": json.dumps(act_arr, ensure_ascii=False),
                              "parameter_record_json": json.dumps(par_arr, ensure_ascii=False),
                              "control_record_json": json.dumps(ctl_arr, ensure_ascii=False),
                              "generation_t": gen, "emission_t": emi,
                              "standard_reference": "T/CSES 144-2024 7.2.1.2/附录D表D.1",
                              "reason_code": "CALC_OK" if p != "NH3" else "NH3_EF_ZERO_STANDARD"})
                stats["calculated"] += 1
            else:
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "information_insufficient",
                              "method": "", "activity_record_json": "[]", "parameter_record_json": "[]",
                              "control_record_json": "[]", "generation_t": "", "emission_t": "",
                              "standard_reference": "T/CSES 144-2024 7.2.1.2/附录D表D.1",
                              "reason_code": r.get("reason", "INSUFFICIENT")})
                stats["information_insufficient"] += 1

    # ---- 输出 ----
    pd.DataFrame(decisions).to_csv(os.path.join(OUT, "source_decisions.csv"), index=False, encoding="utf-8-sig")
    pd.DataFrame(dispositions).to_csv(os.path.join(OUT, "generic_source_disposition.csv"), index=False, encoding="utf-8-sig")
    items_df = pd.DataFrame(items)
    items_df.to_csv(os.path.join(OUT, "generic_inventory_items.csv"), index=False, encoding="utf-8-sig")

    print("decisions:", len(decisions), "| items:", len(items_df))
    print("stats:", stats)
    print("item status counts:\n", items_df["status"].value_counts(dropna=False).to_string())


