def num(v):
    try:
        f = float(v)
        return f if math.isfinite(f) else None
    except (TypeError, ValueError):
        return None


def industry_to_class(code):
    c = int(code)
    if c in D44:
        return "POWER", "CLASS_POWER_D44"
    if c in D45:
        return "INDUSTRIAL", "CLASS_INDUSTRIAL_D45"
    if 1300 <= c <= 4399:
        return "INDUSTRIAL", "CLASS_INDUSTRIAL_C"
    if 600 <= c <= 1299:
        return "INDUSTRIAL", "CLASS_INDUSTRIAL_B"
    return "OUT_OF_SCOPE", "CLASS_OUT_OF_SCOPE"


