        v = row["电站锅炉燃烧技术"]
    else:
        v = row["工业锅炉燃烧技术"]
    return v if pd.notna(v) else None


def lnb_of(row):
    if pd.notna(row["电站锅炉/燃气轮机编号"]):
        v = row["是否采用低氮燃烧技术"]
    else:
        v = row["是否采用低氮燃烧技术.1"]
    return 1 if (pd.notna(v) and str(v).strip() == "是") else 0


def load_facility_map():
    fac = pd.read_excel(os.path.join(IN, "基101-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    m = {}
    for r in fac.itertuples(index=False):
        credit = r[2] if pd.notna(r[2]) else None
        org = r[1] if pd.notna(r[1]) else None
        key = str(credit) if credit else (str(org) if org else None)
        if key is None:
            continue
        outlet = r[11] if pd.notna(r[11]) else None
        if outlet not in ("DZGL", "GYGL"):
            continue
        m.setdefault((key, outlet), []).append({
            "name": r[10] if pd.notna(r[10]) else None,
            "process": r[15] if pd.notna(r[15]) else None,
            "eff": num(r[16]),
        })
    return m


def match_a1(kw_list, process, default):
    if process is None:
        return None
    p = str(process)
    for kw, v in kw_list:
        if kw in p:
            return v
    return default


def control_eta(facilities, name_kw, a1_kw, default_a1):
    """某类治理设施去除效率。返回 (eta, mode) — mode: NO_FACILITY/REPORTED/TABLE_A1/UNKNOWN"""
    cands = [f for f in facilities if f["name"] and name_kw in f["name"]]
    if not cands:
        return None, "NO_FACILITY"
    best = None
    for f in cands:
        if f["eff"] is not None and 0 <= f["eff"] <= 100:
            v = f["eff"] / 100.0
            if best is None or v > best[0]:
                best = (v, "REPORTED")
        elif f["eff"] is None:
            a1 = match_a1(a1_kw, f["process"], default_a1)
            if a1 is not None:
                v = a1 / 100.0
                if best is None or v > best[0]:
                    best = (v, "TABLE_A1")
    if best is None:
        return None, "UNKNOWN"
    return best[0], best[1]


def pm_eta(facilities):
    """除尘设施: 返回 (eta_pm25, eta_pm10, mode)"""
    cands = [f for f in facilities if f["name"] and "除尘" in f["name"]]
    if not cands:
        return 0.0, 0.0, "NO_FACILITY"
    best25 = best10 = None
    for f in cands:
        if f["eff"] is not None and 0 <= f["eff"] <= 100:
            v = f["eff"] / 100.0
            if best25 is None or v > best25[0]:
                best25 = (v, "REPORTED")
            if best10 is None or v > best10[0]:
                best10 = (v, "REPORTED")
        elif f["eff"] is None:
            a25 = match_a1(A1_PM25, f["process"], A1_OTHER_DUST[0])
            a10 = match_a1(A1_PM25_10, f["process"], A1_OTHER_DUST[1])
            if a25 is not None and (best25 is None or a25 / 100.0 > best25[0]):
                best25 = (a25 / 100.0, "TABLE_A1")
            if a10 is not None and (best10 is None or a10 / 100.0 > best10[0]):
                best10 = (a10 / 100.0, "TABLE_A1")
    if best25 is None or best10 is None:
        return None, None, "UNKNOWN"
    return best25[0], best10[0], best25[1]


def component_ef(sector, fuel_name, tech, qual, capacity_mw):
    """返回 (ef_dict[pollutant]=(ef, mode, unit), None) 或 (None, reason_code)"""
    if fuel_name in WASTE_FUELS:
        return None, "WASTE_FUEL"
    if fuel_name in UNMAPPABLE_FUELS:
        return None, "FUEL_NO_EF"
    d1_fuel = FUEL_MAP.get(fuel_name)
    if d1_fuel is None:
        return None, "FUEL_NO_EF"
    if d1_fuel == "煤炭":
        t = TECH_MAP.get(tech) if tech else None
        if t is None:
            return None, "TECH_UNKNOWN"
        row = D1[sector]["煤炭"][t]
        cp = C_PARAMS[sector][t]
    elif d1_fuel in ("焦炭", "煤矸石"):
        row = D1[sector][d1_fuel]["不分技术"]
        t = TECH_MAP.get(tech) if tech else None
        cp = C_PARAMS[sector][t] if t else C_PARAMS[sector]["煤粉炉"]
    elif d1_fuel in GAS_FUELS:
        row = D1[sector][d1_fuel][GAS_TECH]
        cp = None
    else:
        row = D1[sector][d1_fuel][LIQUID_TECH]
        cp = None

    ef = {}
    for p in POLLUTANTS:
        if p == "NH3":
            ef[p] = (0.0, "ZERO_STANDARD", "g/kg")
            continue
        v = row.get(p)
        if p == "SO2" and v == "MB":
            s = qual.get("s")
            if s is None:
                return None, "SO2_NO_SULFUR"
            ef[p] = (2.0 * s * (1.0 - SR[sector]), "MASS_BALANCE_SO2", "g/kg")
            continue
        if p in ("PM25", "PM10", "BC", "OC") and v == "MB":
            ash = qual.get("ash")
            if ash is None:
                return None, "PM_NO_ASH"
            ar = cp["ar"]
            base = 10.0 * ash * (1.0 - ar)
            if p == "PM25":
                ef[p] = (base * cp["f25"], "MASS_BALANCE_PM", "g/kg")
            elif p == "PM10":
                ef[p] = (base * cp["f10"], "MASS_BALANCE_PM", "g/kg")
            elif p == "BC":
                ef[p] = (base * cp["f25"] * cp["fBC"], "MASS_BALANCE_PM", "g/kg")
            else:
                ef[p] = (base * cp["f25"] * cp["fOC"], "MASS_BALANCE_PM", "g/kg")
            continue
        if p == "NOx" and v == "CAPACITY":
            if capacity_mw is None:
                return None, "NOX_NO_CAPACITY"
            if capacity_mw <= 100:
                v = 8.96
            elif capacity_mw < 300:
                v = 8.19
            else:
                v = 7.21
            ef[p] = (v, "TABLE_D1_CAPACITY", "g/kg")
            continue
        ef[p] = (float(v), "TABLE_D1", row["unit"])
    return ef, None


def source_components(row):
    """返回组件列表 [{id, fuel, value, unit, qual}]"""
    comps = []
    for n, col_fuel, col_val, col_unit, col_s, col_ash in (
        (1, "燃料1类型", "燃料1消耗量", "燃料1消耗量单位", "燃料一平均收到基含硫量", "燃料一平均收到基灰分（%）"),
        (2, "燃料2类型", "燃料2消耗量", "燃料2消耗量单位", "燃料二平均收到基含硫量", "燃料二平均收到基灰分（%）"),
    ):
        fuel = row[col_fuel] if pd.notna(row[col_fuel]) else None
        v = num(row[col_val])
        if fuel is None or v is None or v <= 0:
            continue
        u = row[col_unit] if pd.notna(row[col_unit]) else None
        qual = {"s": num(row[col_s]), "ash": num(row[col_ash])}
        comps.append({"id": f"F{n}", "fuel": fuel, "value": v, "unit": u, "qual": qual})
    return comps


def calc_source(sector, row, comps, capacity_mw, tech):
    """逐污染物汇总产生量。返回 {pollutant: {status, gen, reason, comp:[...]}}"""
    results = {}
    for p in POLLUTANTS:
        gen_parts = []
        fail = None
        for c in comps:
            ef, reason = component_ef(sector, c["fuel"], tech, c["qual"], capacity_mw)
            if reason is not None:
                fail = f"{c['id']}:{reason}"
                break
            efv, mode, unit = ef[p]
            # 活动水平换算: 气体 万m3 -> m3; 固体/液体 吨 -> kg; E(t) = kg(或m3) × EF / 1e6
            if c["unit"] and "万立方米" in str(c["unit"]):
                act_kg = c["value"] * 1e4
            else:
                act_kg = c["value"] * 1000.0
            gen_parts.append({"id": c["id"], "gen": act_kg * efv / 1e6, "ef": efv, "mode": mode, "unit": unit})
        if fail is not None:
            results[p] = {"status": "information_insufficient", "reason": fail, "gen": None, "comp": []}
        else:
            results[p] = {"status": "calculated", "gen": sum(x["gen"] for x in gen_parts), "comp": gen_parts}
    return results


def apply_control(row, facilities, results):
    """填入排放量(扣治理)。就地修改 results。"""
    # SO2
    eta_so2, so2_mode = control_eta(facilities, "脱硫", A1_SO2, 40)
    # NOx
    lnb = lnb_of(row)
    eta_nox, nox_mode = control_eta(facilities, "脱硝", A1_NOX, 20)
    if nox_mode == "NO_FACILITY":
        eta_nox = 0.0
        nox_desc = "NO_FACILITY"
        nox_proc = None
    else:
        nox_desc = nox_mode
        nox_proc = None
        # 检查工艺名是否已含"低氮燃烧"(表A.1合并值, 不再叠加)
        cands = [f for f in facilities if f["name"] and "脱硝" in f["name"]]
        for f in cands:
            if f["process"] and "低氮燃烧" in str(f["process"]):
                nox_proc = True
    if lnb and nox_proc is not True:
        if nox_mode == "NO_FACILITY":
            eta_nox = 0.22
            nox_desc = "LNB_TABLE_A1"
        elif eta_nox is not None:
            eta_nox = 1.0 - (1.0 - 0.22) * (1.0 - eta_nox)
            nox_desc = nox_desc + "+LNB_SERIES"
    elif lnb and nox_proc is True:
        nox_desc = nox_desc + "_INCL_LNB"
    # PM
    eta_pm25, eta_pm10, pm_mode = pm_eta(facilities)
    # VOC: 锅炉排放口(DZGL/GYGL)未挂接VOCs治理设施 -> η=0
    eta = {
        "SO2": (eta_so2, so2_mode),
        "NOx": (eta_nox, nox_desc),
        "CO": (0.0, "NO_FACILITY"),
        "VOC": (0.0, "NO_FACILITY"),
        "PM2.5": (eta_pm25, pm_mode),
        "PM10": (eta_pm10, pm_mode),
        "BC": (eta_pm25, pm_mode),
        "OC": (eta_pm25, pm_mode),
        "NH3": (0.0, "NO_FACILITY"),
    }
    for p, r in results.items():
        if r["status"] != "calculated":
            continue
        e, mode = eta[p]
        if e is None:
            r["status"] = "information_insufficient"
            r["reason"] = "CONTROL_EFF_UNKNOWN"
            r["emi"] = None
            continue
        r["emi"] = r["gen"] * (1.0 - e)
        r["eta"] = e
        r["eta_mode"] = mode


def main():
    df = pd.read_excel(os.path.join(IN, "基102-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    with open(os.path.join(IN, "source_identity_index.json"), encoding="utf-8") as f:
        idx = json.load(f)
    recs = idx["records"]
    assert len(recs) == len(df), (len(recs), len(df))
    sid_by_row = {r["source_row"]: r["source_id"] for r in recs}
    df["source_id"] = df.index.map(lambda i: sid_by_row[i + 2])
    fac_map = load_facility_map()

    decisions, dispositions, items = [], [], []
    stats = {"calculated": 0, "not_involved": 0, "information_insufficient": 0, "source_data_invalid": 0}
    reason_counts = {}

    for _, row in df.iterrows():
        sid = row["source_id"]
        cls, cls_reason = industry_to_class(row["行业类别代码"])
        fuel1 = fuel1_of(row)
        is_power_device = pd.notna(row["电站锅炉/燃气轮机编号"])
        outlet_code = "DZGL" if is_power_device else "GYGL"

        if cls == "POWER" and fuel1 in WASTE_FUELS:
            decided, disp, reason = "OUT_OF_SCOPE", "out_of_scope", "WASTE_INCINERATION_CH13"
        elif cls == "POWER":
            decided, disp, reason = "POWER", "in_scope", cls_reason
        else:
            decided, disp, reason = cls, "out_of_scope", cls_reason

        decisions.append({"source_id": sid, "requested_target": "POWER", "decided_target": decided,
                          "disposition": disp, "reason_code": reason})
        dispositions.append({"source_id": sid, "target": decided, "disposition": disp, "reason_code": reason})

        if decided != "POWER":
            for p in POLLUTANTS:
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "not_involved",
                              "method": "", "activity_record_json": "[]", "parameter_record_json": "[]",
                              "control_record_json": "[]", "generation_t": "", "emission_t": "",
                              "standard_reference": "", "reason_code": "NOT_IN_REQUESTED_TARGET"})
            stats["not_involved"] += len(POLLUTANTS)
            continue

        comps = source_components(row)
        sector = "热力生产和供应" if int(row["行业类别代码"]) == 4430 else "电力生产"
        cap_mw = num(row["对应机组装机容量（万千瓦）"])
        cap_mw = cap_mw * 10.0 if cap_mw is not None else None
        tech = tech_of(row)

        credit = row["统一社会信用代码"] if pd.notna(row["统一社会信用代码"]) else (row["组织机构代码"] if pd.notna(row["组织机构代码"]) else None)
        facilities = fac_map.get((str(credit), outlet_code), []) if credit else []

        if not comps:
            for p in POLLUTANTS:
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "information_insufficient",
                              "method": "", "activity_record_json": "[]", "parameter_record_json": "[]",
                              "control_record_json": "[]", "generation_t": "", "emission_t": "",
                              "standard_reference": "T/CSES 144-2024 7.2", "reason_code": "NO_ACTIVITY"})
            stats["information_insufficient"] += len(POLLUTANTS)
            continue

        results = calc_source(sector, row, comps, cap_mw, tech)
        apply_control(row, facilities, results)

        for p in POLLUTANTS:
            r = results[p]
            if r["status"] == "calculated":
                act_arr = [{"component_id": c["id"], "value": c["value"], "unit": c["unit"]} for c in comps]
                par_arr = [{"component_id": c["id"], "parameter_id": f"EF_{p}", "mode": c["mode"],
                            "value": c["ef"], "unit": c["unit"]} for c in r["comp"]]
                if p == "PM10":
                    ctl_arr = [{"component_id": c["id"], "method": r["eta_mode"], "efficiency": r["eta"],
                                "fine_efficiency": r["eta"], "coarse_efficiency": r["eta"]} for c in r["comp"]]
                else:
                    ctl_arr = [{"component_id": c["id"], "method": r["eta_mode"], "efficiency": r["eta"],
                                "fine_efficiency": "", "coarse_efficiency": ""} for c in r["comp"]]
                method = "E=A×EF×(1−η) 公式(2)" if r["eta"] > 0 else "E=A×EF 公式(2), η=0"
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "calculated",
                              "method": method,
                              "activity_record_json": json.dumps(act_arr, ensure_ascii=False),
                              "parameter_record_json": json.dumps(par_arr, ensure_ascii=False),
                              "control_record_json": json.dumps(ctl_arr, ensure_ascii=False),
                              "generation_t": round(r["gen"], 6), "emission_t": round(r["emi"], 6),
                              "standard_reference": "T/CSES 144-2024 7.2.1.2/附录D表D.1",
                              "reason_code": "CALC_OK" if p != "NH3" else "NH3_EF_ZERO_STANDARD"})
                stats["calculated"] += 1
                rc = "CALC_OK" if p != "NH3" else "NH3_EF_ZERO_STANDARD"
            else:
                items.append({"source_id": sid, "target": "POWER", "pollutant": p, "status": "information_insufficient",
                              "method": "", "activity_record_json": "[]", "parameter_record_json": "[]",
                              "control_record_json": "[]", "generation_t": "", "emission_t": "",
                              "standard_reference": "T/CSES 144-2024 7.2.1.2/附录D表D.1",
                              "reason_code": r.get("reason", "INSUFFICIENT")})
                stats["information_insufficient"] += 1
                rc = r.get("reason", "INSUFFICIENT")
            reason_counts[rc] = reason_counts.get(rc, 0) + 1

    pd.DataFrame(decisions).to_csv(os.path.join(OUT, "source_decisions.csv"), index=False, encoding="utf-8-sig")
    pd.DataFrame(dispositions).to_csv(os.path.join(OUT, "generic_source_disposition.csv"), index=False, encoding="utf-8-sig")
    items_df = pd.DataFrame(items)
    items_df.to_csv(os.path.join(OUT, "generic_inventory_items.csv"), index=False, encoding="utf-8-sig")

    print("decisions:", len(decisions), "| items:", len(items_df))
    print("stats:", stats)
    print("reason_counts:", json.dumps(reason_counts, ensure_ascii=False, indent=1))


if __name__ == "__main__":
    main()
